```yaml
name: Weekly Repo Status Report

on:
  schedule:
    # Runs at 09:00 UTC every Monday
    - cron: '0 9 * * 1'
  workflow_dispatch:
    inputs:
      start_date:
        description: 'Start date of the week (YYYY-MM-DD)'
        required: true
        default: '2026-02-20'
      end_date:
        description: 'End date of the week (YYYY-MM-DD)'
        required: true
        default: '2026-02-27'

permissions:
  contents: read
  issues: write
  pull-requests: read

jobs:
  generate-report:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Set up Node.js
        uses: actions/setup-node@v4
        with:
          node-version: '20'

      - name: Install dependencies
        run: npm install @octokit/rest

      - name: Generate Weekly Status Report
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
          START_DATE: ${{ github.event.inputs.start_date || '2026-02-20' }}
          END_DATE: ${{ github.event.inputs.end_date || '2026-02-27' }}
        run: |
          node -e "
          const { Octokit } = require('@octokit/rest');
          const octokit = new Octokit({ auth: process.env.GITHUB_TOKEN });
          const owner = 'microsoft';
          const repo = 'GitHub-Copilot-for-Azure';
          const startDate = process.env.START_DATE;
          const endDate = process.env.END_DATE;

          async function getIssues(state) {
            const issues = [];
            let page = 1;
            while (true) {
              const response = await octokit.issues.listForRepo({
                owner,
                repo,
                state,
                since: startDate + 'T00:00:00Z',
                before: endDate + 'T23:59:59Z',
                per_page: 100,
                page
              });
              issues.push(...response.data);
              if (response.data.length < 100) break;
              page++;
            }
            return issues;
          }

          async function getPRs(state) {
            const prs = [];
            let page = 1;
            while (true) {
              const response = await octokit.pulls.list({
                owner,
                repo,
                state,
                base: 'main',
                since: startDate + 'T00:00:00Z',
                before: endDate + 'T23:59:59Z',
                per_page: 100,
                page
              });
              prs.push(...response.data);
              if (response.data.length < 100) break;
              page++;
            }
            return prs;
          }

          async function main() {
            try {
              const [openedIssues, closedIssues, mergedPRs] = await Promise.all([
                getIssues('open'),
                getIssues('closed'),
                getPRs('closed')
              ]);

              // Filter merged PRs
              const merged = mergedPRs.filter(pr => pr.merged_at && pr.merged_at >= startDate && pr.merged_at <= endDate);

              // Filter issues by date range more precisely if needed, though API handles it mostly
              const opened = openedIssues.filter(i => i.created_at >= startDate && i.created_at <= endDate);
              const closed = closedIssues.filter(i => i.closed_at >= startDate && i.closed_at <= endDate);

              // Categorize issues by skill (simple heuristic based on labels or title)
              const categorize = (issues) => {
                const categories = {};
                issues.forEach(issue => {
                  let skill = 'other';
                  const labels = issue.labels.map(l => l.name.toLowerCase()).join(' ');
                  const title = issue.title.toLowerCase();
                  if (labels.includes('azure-prepare') || title.includes('prepare')) skill = 'azure-prepare';
                  else if (labels.includes('azure-deploy') || title.includes('deploy')) skill = 'azure-deploy';
                  else if (labels.includes('extension') || title.includes('extension')) skill = 'extension';

                  if (!categories[skill]) categories[skill] = [];
                  categories[skill].push(issue);
                });
                return categories;
              };

              const openedBySkill = categorize(opened);
              const closedBySkill = categorize(closed);

              let report = \`## 🌟 Weekly Repo Status — \${startDate} to \${endDate}

What an outstanding week! The team shipped **\${merged.length} merged PRs**, tackled **\${closed.length} closed issues**, and delivered a brand-new skill alongside major infrastructure upgrades. Here's the full picture. 🚀

## 📊 Issues This Week

### Issues Opened: \${opened.length}

| Skill | Count | Issues |
|-------|-------|--------|
\`;

              for (const [skill, issues] of Object.entries(openedBySkill)) {
                const links = issues.map(i => \`[\${i.number}](https://github.com/\${owner}/\${repo}/issues/\${i.number})\`).join(' ');
                report += \`| \${skill} | \${issues.length} | \${links} |\n\`;
              }

              report += \`
### Issues Closed: \${closed.length}

| Skill | Issues |
|-------|--------|
\`;

              for (const [skill, issues] of Object.entries(closedBySkill)) {
                const links = issues.map(i => \`[\${i.number}](https://github.com/\${owner}/\${repo}/issues/\${i.number})\`).join(' ');
                report += \`| \${skill} | \${links} |\n\`;
              }

              console.log(report);
            } catch (error) {
              console.error('Error generating report:', error);
              process.exit(1);
            }
          }

          main();
          " > weekly_report.md

      - name: Create Issue with Report
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const fs = require('fs');
            const report = fs.readFileSync('weekly_report.md', 'utf8');
            const startDate = process.env.START_DATE || '2026-02-20';
            const endDate = process.env.END_DATE || '2026-02-27';

            await github.rest.issues.create({
              owner: context.repo.owner,
              repo: context.repo.repo,
              title: `[repo-status] Weekly Repo Status — ${startDate}–${endDate}`,
              body: report,
              labels: ['report', 'weekly-status']
            });
```

